mkdir -p "$HOME/diffs"
while IFS='|' read -r BUG COMMIT TESTFILE; do
  [ -z "$BUG" ] && continue
  case $BUG in
    1) FILES="lib/ansible/galaxy/collection.py" ;;
    2) FILES="lib/ansible/utils/version.py" ;;
    3) FILES="lib/ansible/module_utils/facts/system/distribution.py" ;;
    4) FILES="lib/ansible/playbook/collectionsearch.py" ;;
    5) FILES="lib/ansible/module_utils/common/validation.py" ;;
    6) FILES="lib/ansible/galaxy/collection.py" ;;
    7) FILES="lib/ansible/module_utils/network/eos/config/vlans/vlans.py" ;;
    8) FILES="lib/ansible/plugins/shell/powershell.py" ;;
    9) FILES="lib/ansible/modules/packaging/os/redhat_subscription.py" ;;
    10) FILES="lib/ansible/modules/system/pamd.py" ;;
    11) FILES="lib/ansible/modules/network/ios/ios_banner.py" ;;
    12) FILES="lib/ansible/plugins/lookup/env.py" ;;
    13) FILES="lib/ansible/cli/galaxy.py" ;;
    14) FILES="lib/ansible/galaxy/api.py" ;;
    15) FILES="lib/ansible/modules/network/eos/eos_eapi.py" ;;
    16) FILES="lib/ansible/module_utils/facts/hardware/linux.py" ;;
    17) FILES="lib/ansible/module_utils/facts/hardware/linux.py" ;;
    18) FILES="lib/ansible/cli/galaxy.py setup.py" ;;
  esac
  OUT="$HOME/diffs/bug_$BUG.diff"
  : > "$OUT"
  for f in $FILES; do
    unzip -p "$ROOT/_work/downloads/ansible-$BUG.zip" "ansible-$COMMIT/$f" > /tmp/orig_file
    diff -u --label "a/$f" --label "b/$f" /tmp/orig_file "$HOME/w/bug_$BUG/ansible-$COMMIT/$f" >> "$OUT" || true
  done
  echo "===== bug $BUG ($COMMIT) ====="
  cat "$OUT"
done < "$ROOT/_work/buglist.txt"
